def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse right, skipping every alternate cell
            for j in range(0, len(grid[i]), 2):
                result.append(grid[i][j])
        else:
            # Traverse left, appending only the center column when i is odd
            if len(grid[i]) > 1:
                result.append(grid[i][1])
    return result

def findValidPair(s: str) -> str:
    from collections import Counter

    count = Counter(s)
    for i in range(len(s) - 1):
        a, b = s[i], s[i + 1]
        if a != b and count[a] == int(a) and count[b] == int(b):
            return a + b
    return ""

