def totalNumbers(digits: List[int]) -> int:
    from itertools import permutations

    distinct_numbers = set()

    for p in permutations(digits, 3):
        if p[0] != 0 and p[2] % 2 == 0:
            distinct_numbers.add(p)

    return len(distinct_numbers)

def reverseDegree(s: str) -> int:
    total = 0
    for index, char in enumerate(s):
        position_in_reversed_alphabet = (ord('z') - ord(char) + 1)
        total += position_in_reversed_alphabet * (index + 1)
    return total

