def maximumAmount(coins: List[List[int]]) -> int:
    m = len(coins)
    n = len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]

    for i in range(m):
        for j in range(n):
            for k in range(3):
                if i == 0 and j == 0:
                    continue
                # Coming from the left
                if j > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + coins[i][j])
                # Coming from above
                if i > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + coins[i][j])
                # Neutralizing a robber from left
                if j > 0 and k > 0 and coins[i][j] < 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + coins[i][j])
                # Neutralizing a robber from above
                if i > 0 and k > 0 and coins[i][j] < 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + coins[i][j])

    return max(dp[m-1][n-1][k] for k in range(3))

