from collections import defaultdict, deque


def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    # Sort edges by weight
    edges.sort(key=lambda x: x[2])
    left, right = 0, 10**6
    result = -1

    def canReachNode0(maxWeight):
        graph = defaultdict(list)
        for u, v, w in edges:
            if w <= maxWeight:
                graph[v].append(u)  # Build graph from v to u

        visited = [False] * n
        queue = deque()
        queue.append(0)
        visited[0] = True

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return all(visited)

    while left <= right:
        mid = (left + right) // 2
        if canReachNode0(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    if result == -1:
        return -1

    # Check if the resulting graph can have at most threshold edges per node
    outgoing_count = [0] * n
    for u, v, w in edges:
        if w <= result:
            outgoing_count[u] += 1
            if outgoing_count[u] > threshold:
                return -1

    return result

from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    # dp[i][c] will be the minimum cost to paint up to house i with color c
    dp = [[float('inf')] * 3 for _ in range(n)]
    # Initialize the first house with its corresponding costs
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill in the dp table for each house
    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(dp[i - 1][(j + 1) % 3], dp[i - 1][(j + 2) % 3])

    # Total costs for painting
    min_cost = float('inf')

    # Handle the equidistant condition for two halves
    for first_half_color in range(3):
        for second_half_color in range(3):
            if first_half_color != second_half_color:
                total_cost = 0
                for i in range(n // 2):
                    total_cost += dp[i][first_half_color]  # First half
                for i in range(n // 2, n):
                    total_cost += dp[i][second_half_color]  # Second half
                min_cost = min(min_cost, total_cost)

    return min_cost

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in sorted(events, key=lambda x: int(x[1])):
        event_type, timestamp, *details = event
        timestamp = int(timestamp)

        # Update online status before processing the event
        for user in range(numberOfUsers):
            if not online_status[user] and timestamp >= offline_until[user]:
                online_status[user] = True

        if event_type == "OFFLINE":
            user_id = int(details[0])
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            mentions_string = details[0]
            if mentions_string == "ALL":
                for user in range(numberOfUsers):
                    mentions[user] += 1
            elif mentions_string == "HERE":
                for user in range(numberOfUsers):
                    if online_status[user]:
                        mentions[user] += 1
            else:
                for mention in mentions_string.split():
                    if mention.startswith("id"):
                        user_id = int(mention[2:])
                        mentions[user_id] += 1

    return mentions

from typing import List

def maxFreeTime(eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
    n = len(startTime)
    prev_end = 0
    free_intervals = []

    # Collect the free intervals before the meetings start
    if startTime[0] > 0:
        free_intervals.append((0, startTime[0]))

    for i in range(n):
        if startTime[i] > prev_end:
            free_intervals.append((prev_end, startTime[i]))
        prev_end = endTime[i]

    # Collect free time after the last meeting
    if prev_end < eventTime:
        free_intervals.append((prev_end, eventTime))

    # Calculate gaps between meetings
    gaps = []
    for i in range(1, n):
        gap = startTime[i] - endTime[i - 1]
        if gap > 0:
            gaps.append(gap)

    # Sort gaps in descending order to maximize free time by rescheduling
    gaps.sort(reverse=True)
    max_free_time = 0

    # Calculate maximum free time without any rescheduling
    if free_intervals:
        max_free_time = max(free_end - free_start for free_start, free_end in free_intervals)

    # Calculate extra free time by moving up to k meetings
    extra_free_time = sum(gaps[:k])

    return max(max_free_time, extra_free_time)
